css:
.container {
  margin: auto;
  font-weight: 900;
  font-size: 6rem;
  display: flex;
}

.toggle {
  margin-top: 10px;
  transform: scale(0.85) translateX(0.5rem);
  width: 60px;
  height: 155px;
  background: linear-gradient(744deg, #ea6f62 20%, #cccccc00 40%, #6bae67 80%);
  background-color: #ea6f62;
  border-radius: 1.8rem;
  padding: 0.25rem 0;
  cursor: pointer;
  display: flex;
  justify-content: center;
  transition: background 0.3s 0.3s;
  transition-delay: 0.35s;
}

.toggle__circle {
  color: hsl(0, 0%, 30%);
  width: 20px;
  height: 20px;
  background-color: hsla(0, 0%, 95%, 0);
  outline-style: solid;
  outline-width: 17.5px;
  border-radius: 50%;
  margin-top: calc(155px - 20px * 2.25);
  transition: margin 0.4s ease-in;
}

.toggle-text {
  background: linear-gradient(0deg, #4d4d4d 0%, #4d4d4d88 50%, #56704c2e 56.5%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  display: flex;
  flex-direction: column;
  line-height: 0.8;
}

#check:checked + .toggle > .toggle__circle {
  margin-top: calc(20px / 1.25);
}

#check:checked + .toggle ~ .toggle-text {
  background: linear-gradient(
    180deg,
    #4d4d4d 0%,
    #4d4d4d88 45%,
    #56704c2e 47.5%
  );
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

/*vvunusedvv*/
@keyframes grad {
  0% {
    background: linear-gradient(
      0deg,
      #4d4d4d 0%,
      #4d4d4d88 50%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  10% {
    background: linear-gradient(
      2deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  20% {
    background: linear-gradient(
      10deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  40% {
    background: linear-gradient(
      45deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  50% {
    background: linear-gradient(
      90deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  60% {
    background: linear-gradient(
      135deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  75% {
    background: linear-gradient(
      150deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  90% {
    background: linear-gradient(
      170deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  95% {
    background: linear-gradient(
      175deg,
      #4d4d4d 0%,
      #4d4d4d88 47.5%,
      #56704c2e 56.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
  100% {
    background: linear-gradient(
      180deg,
      #4d4d4d 0%,
      #4d4d4d88 45%,
      #56704c2e 47.5%
    );
    -webkit-background-clip: text;
    background-clip: text;
  }
}

#check:checked + .toggle {
  background-color: #6bae67;
}
